import shutil
from datetime import date
from decimal import Decimal


def start_table(invoices, path):
    # Last night's table, with two invoices. Don't change this.
    shutil.rmtree(path, ignore_errors=True)  # start from an empty folder on every run
    last_night = spark.createDataFrame(
        [
            ("INV-000001", "ACC-0001", date(2025, 10, 14), date(2025, 11, 13), "open", Decimal("244.00")),
            ("INV-000090", "ACC-0004", date(2025, 9, 30), date(2025, 10, 30), "void", Decimal("99.00")),
        ],
        invoices.schema,
    )
    last_night.write.format("delta").save(path)


def save(invoices, path):
    # Replace the table with tonight's invoices.
    invoices.write.format("delta").mode("append").save(path)


def load(path):
    # Read the table the way the reports do.
    return spark.read.parquet(path)


def solve(invoices):
    path = "/tmp/billing/invoices"
    start_table(invoices, path)
    save(invoices, path)
    return load(path)
